import queue

import pytest


def accepted(cap: int, xs: list[int]) -> int:
    """Count how many elements of xs a bounded queue accepts without blocking.

    Creates a queue holding at most `cap` integers and tries to put each
    element of xs in order without blocking. Stops at the first rejected
    put (queue full) and returns the number of puts accepted before that.
    A capacity of zero or less accepts nothing, so the result is 0.
    """
    if cap <= 0:
        # queue.Queue treats maxsize <= 0 as unbounded, so handle it here.
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        count += 1
    return count


def test_stops_when_full() -> None:
    assert accepted(2, [10, 20, 30, 40]) == 2


def test_capacity_larger_than_input() -> None:
    assert accepted(10, [1, 2, 3]) == 3


def test_capacity_equals_length() -> None:
    assert accepted(3, [1, 2, 3]) == 3


def test_empty_input() -> None:
    assert accepted(5, []) == 0


def test_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_negative_capacity() -> None:
    assert accepted(-1, [1, 2, 3]) == 0


def test_duplicates_are_counted() -> None:
    assert accepted(3, [7, 7, 7, 7, 7]) == 3


@pytest.mark.parametrize("cap", range(0, 8))
def test_matches_min_of_cap_and_length(cap: int) -> None:
    xs = [1, 2, 3, 4, 5]
    assert accepted(cap, xs) == min(cap, len(xs))


def test_input_not_modified() -> None:
    xs = [1, 2, 3, 4]
    accepted(2, xs)
    assert xs == [1, 2, 3, 4]

